!function(){"use strict";function carteraClienteCtrl($scope,commonSvc,mS,clienteSvc,fS){const Toast=Swal.mixin({toast:!0,position:"top-end",showConfirmButton:!1,timer:1e3,timerProgressBar:!0,didOpen:toast=>{toast.addEventListener("mouseenter",Swal.stopTimer),toast.addEventListener("mouseleave",Swal.resumeTimer)}});$scope.dataSearch={fechaInicio:new Date,fechaFin:new Date,byCliente:0},$scope.moreSearchOptions=!1,$scope.dataSearch.verDetalleDoc=!1,$scope.total=0,$scope.abono=0,$scope.saldo=0,$scope.format=null,$scope.initiload=async function(){try{showLoader(),await commonSvc.getEstabAsign().then(response=>{$scope.establecimientos=response,$scope.establecimientos.length>0?$scope.dataSearch.codEstab=$scope.establecimientos[0].codEstab:Toast.fire({icon:"warning",html:"NO TIENES ASIGNADO NINGÚN ESTABLECIMIENTO"})}).catch(error=>{hideLoader(),console.log(error)}),await commonSvc.getEstadoDocByCodDoc("CCL").then(response=>{$scope.estadoDocumentos=response}),hideLoader()}catch(error){hideLoader(),console.log(error)}},$scope.initiload(),$scope.resultRangeFilter=function(item){$scope.dataSearch.fechaInicio=item.startDate,$scope.dataSearch.fechaFin=item.endDate},$scope.clienteSearch=function(textSearch){let query={textSearch:textSearch};if(textSearch.length>2)return clienteSvc.search(query).catch(error=>{console.log(error)})},$scope.onKeyupClienteSearchFiltro=function(){$scope.modelTextSearch||($scope.dataSearch.byCliente=0,$scope.dataSearch.verDetalleDoc=!1)},$scope.selectedClienteSearchFiltro=function(item){$scope.dataSearch.byCliente=item.idCliente},$scope.onClickBtnMore=function(){$scope.moreSearchOptions=!$scope.moreSearchOptions},$scope.isValidForm=function(){if($scope.dataSearch.codEstab)if($scope.dataSearch.fechaInicio){if($scope.dataSearch.fechaFin)return!0;Toast.fire({icon:"warning",html:"Ingrese fecha fin"})}else Toast.fire({icon:"warning",html:"Ingrese fecha de Inicio"});else Toast.fire({icon:"warning",html:"Seleccione el Establecimiento"})},$scope.search=function(){$scope.isValidForm()&&Toast.fire({icon:"warning",html:"No Disponible"})},$scope.exportToExcel=function(){$scope.format="excel",$scope.isValidForm()&&$scope.getReport()},$scope.exportToPDF=function(){$scope.format="pdf",$scope.isValidForm()&&$scope.getReport()},$scope.getReport=function(){let dataParams={codEstab:$scope.dataSearch.codEstab,checkBoxCliente:$scope.dataSearch.byCliente>0,byCliente:$scope.dataSearch.byCliente,checkBoxEstado:$scope.dataSearch.byEstado>0,byEstado:$scope.dataSearch.byEstado,fechaInicio:fS.formatDateTimeZone($scope.dataSearch.fechaInicio),fechaFin:fS.formatDateTimeZone($scope.dataSearch.fechaFin),verDetalleDoc:!($scope.dataSearch.byCliente>0)&&$scope.dataSearch.verDetalleDoc};console.log($scope.dataSearch.byCliente),console.log($scope.dataSearch.verDetalleDoc),console.log(dataParams);const parameters={hasIdUsuarioRol:!0,reportParams:JSON.stringify({hasParams:!1,codigo:"RCCL",format:$scope.format,aditionalParams:[]}),dataParams:JSON.stringify(dataParams)};commonSvc.getReport({parameters:parameters,formatType:$scope.format})},$scope.verDocumento=function(item){commonSvc.viewDetailDocument({id:item.idDocumento,codigoDocumento:item.codigo,size:"xl",windowClass:"uibModalFullScreen"})}}app.controller("carteraClienteCtrl",carteraClienteCtrl),carteraClienteCtrl.$inject=["$scope","commonService","mainService","clienteService","formulario"]}(window.angular);